import { gsap } from 'gsap';
import {
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  ExtrudeGeometry,
  IcosahedronGeometry,
} from 'three/webgpu';
import { uv, mix, color, vec3, time, sin, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Shape, PointLight, Mesh, Color } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'ornamental-divider';

  // ---------------------------------------------------------------
  // Placeholder / primary geometry: a thin machined rule + center jewel
  // (built procedurally so the node is never empty while the GLB loads)
  // ---------------------------------------------------------------
  const ruleGroup = new Group();
  ruleGroup.name = 'divider-rule-group';

  // A thin, gently bevelled bar shape (rounded rectangle) extruded to give it
  // real thickness + a bevel edge so it reads as a machined 3D object.
  const barW = 1.5;
  const barH = 0.045;
  const r = 0.018;
  const shape = new Shape();
  shape.moveTo(-barW / 2 + r, -barH / 2);
  shape.lineTo(barW / 2 - r, -barH / 2);
  shape.quadraticCurveTo(barW / 2, -barH / 2, barW / 2, -barH / 2 + r);
  shape.lineTo(barW / 2, barH / 2 - r);
  shape.quadraticCurveTo(barW / 2, barH / 2, barW / 2 - r, barH / 2);
  shape.lineTo(-barW / 2 + r, barH / 2);
  shape.quadraticCurveTo(-barW / 2, barH / 2, -barW / 2, barH / 2 - r);
  shape.lineTo(-barW / 2, -barH / 2 + r);
  shape.quadraticCurveTo(-barW / 2, -barH / 2, -barW / 2 + r, -barH / 2);

  const barGeo = new ExtrudeGeometry(shape, {
    depth: 0.03,
    bevelEnabled: true,
    bevelThickness: 0.006,
    bevelSize: 0.006,
    bevelSegments: 2,
    curveSegments: 8,
  });
  barGeo.center();

  const inkColor = new Color(colors.ink);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  const ruleMat = new MeshPhysicalNodeMaterial({
    metalness: 0.5,
    roughness: 0.52,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  // Engineered machined-metal gradient across the rule (ink -> subtle paper sheen -> ink)
  const gradientX = uv().x;
  const sheen = mix(color(inkColor), color(paperColor), gradientX.mul(2).sub(1).abs().oneMinus().mul(0.35));
  ruleMat.colorNode = sheen;

  const ruleMesh = new Mesh(barGeo, ruleMat);
  ruleMesh.castShadow = false;
  ruleGroup.add(ruleMesh);

  // Center jewel: faceted gem with clearcoat + emissive accent core so it reads
  // as the single brightest element on the dark stage.
  const jewelGeo = new IcosahedronGeometry(0.085, 0);
  const jewelMat = new MeshPhysicalNodeMaterial({
    metalness: 0.1,
    roughness: 0.15,
    clearcoat: 0.25,
    clearcoatRoughness: 0.1,
    transmission: 0.35,
    ior: 1.5,
    thickness: 0.05,
  });
  jewelMat.colorNode = color(accentColor);
  // subtle idle breathing glow (<=2% type motion budget, TSL-driven, no extra JS ticker)
  const breathe = float(1).add(sin(time.mul(1.6)).mul(0.12));
  jewelMat.emissiveNode = color(accentColor).mul(breathe);

  const jewelMesh = new Mesh(jewelGeo, jewelMat);
  jewelMesh.position.set(0, 0, 0.03);
  ruleGroup.add(jewelMesh);

  root.add(ruleGroup);

  // Node-local rim light to keep the jewel's transmission from reading as black,
  // and to give the accent hue a back-lit signal without exceeding budget.
  const rimLight = new PointLight(accentColor, 0.9, 1.6, 2);
  rimLight.position.set(0.2, 0.15, 0.4);
  root.add(rimLight);

  // ---------------------------------------------------------------
  // Load the actual authored mesh; swap it in when ready.
  // ---------------------------------------------------------------
  let glbScene = null;
  let disposed = false;
  if (config.meshUrl) {
    ctx.glbLoader
      .loadGLB(config.meshUrl)
      .then((gltf) => {
        if (disposed) return;
        glbScene = gltf.scene;
        root.add(glbScene);
        ruleGroup.visible = false;
      })
      .catch(() => {
        // keep procedural fallback visible on failure
      });
  }

  // ---------------------------------------------------------------
  // Interaction: hover rise-in (subtle 0.15 units) + click press-down + emit
  // ---------------------------------------------------------------
  const baseY = 0;
  let hoverTween = null;
  let pressTween = null;

  const onPointerOver = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(root.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(root.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  const onPointerOut = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(root.position, {
      y: baseY,
      duration: 0.9,
      ease: 'power4.out',
    });
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power2.out',
    });
  };

  const onPointerDown = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  };

  const onPointerUp = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out',
    });
  };

  const onClick = () => {
    onPointerDown();
    gsap.delayedCall(0.12, onPointerUp);
    ctx.emit('hub-home.select', { nodeId: config.id ?? 'home-divider' });
    ctx.emit('navigate', { to: 'hub-home' });
  };

  root.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp,
    click: onClick,
  };

  // ---------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------
  root.userData.cleanup = () => {
    disposed = true;
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);

    barGeo.dispose();
    ruleMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();

    root.remove(rimLight);

    if (glbScene) {
      glbScene.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
          mats.forEach((m) => m.dispose && m.dispose());
        }
      });
    }
  };

  return root;
}
